import{_ as e,o as l,c as r,ae as t}from"./chunks/framework.DFTT1zkb.js";const p=JSON.parse('{"title":"快递","description":"","frontmatter":{},"headers":[],"relativePath":"life/couriers.md","filePath":"life/couriers.md"}'),i={name:"life/couriers.md"};function o(n,a,s,h,c,d){return l(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="快递" tabindex="-1">快递 <a class="header-anchor" href="#快递" aria-label="Permalink to &quot;快递&quot;">​</a></h1><h2 id="地址" tabindex="-1">地址 <a class="header-anchor" href="#地址" aria-label="Permalink to &quot;地址&quot;">​</a></h2><p>河北省石家庄市藁城区河北大道601号河北地质大学</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li><strong>推荐写上宿舍楼号和门牌号</strong><ul><li>可有效避免拿错</li><li>万一拿错了还能给对方送回去</li></ul></li><li><strong>电话写自己的</strong><ul><li>取件码会以短信的形式发送到手机上</li><li>同时也方便拿错快递的人联系你</li></ul></li></ul></div><h2 id="邮编" tabindex="-1">邮编 <a class="header-anchor" href="#邮编" aria-label="Permalink to &quot;邮编&quot;">​</a></h2><p>052161</p><h2 id="取快递" tabindex="-1">取快递 <a class="header-anchor" href="#取快递" aria-label="Permalink to &quot;取快递&quot;">​</a></h2><p>学校内有两个驿站，所有快递都会寄存在驿站，寄件也只能自行前往驿站(即使你选择了上门取件)，学校外近距离内无其他驿站</p><h3 id="快递代收点位置" tabindex="-1">快递代收点位置 <a class="header-anchor" href="#快递代收点位置" aria-label="Permalink to &quot;快递代收点位置&quot;">​</a></h3><ul><li>近邻宝快递服务中心</li></ul><p>位于1953街区(集装箱)，普通快递、京东快递都会寄存在此驿站</p><ul><li>菜鸟驿站</li></ul><p>位于白翎运动场(大白棚)南侧，申通、邮政、顺丰快递寄存在此驿站</p><h3 id="取件流程" tabindex="-1">取件流程 <a class="header-anchor" href="#取件流程" aria-label="Permalink to &quot;取件流程&quot;">​</a></h3><ol><li>当快递送达并入库后，你可以在商品物流页/短信通知查到取件码 <ul><li>取件码格式类似于<code>xx-y-zzzz</code>，其中<code>xx</code>为货架号，<code>y</code>为在该货架的层数</li></ul></li><li>去驿站找到你快递所在的<strong>货架</strong></li><li>按<strong>层数</strong>找你的快递</li><li>核对<strong>取件码后四位、收货地址、电话尾号、姓名</strong>是否与本人一致</li><li>前往对应的APP出示身份码(普通快递需使用拼多多身份码取件、京东使用兔喜生活、申通和邮政使用淘宝、顺丰使用驿收发)</li></ol><h3 id="取件太乱了记不清" tabindex="-1">取件太乱了记不清？ <a class="header-anchor" href="#取件太乱了记不清" aria-label="Permalink to &quot;取件太乱了记不清？&quot;">​</a></h3><p>浏览器访问<strong>河地大几何地图</strong><a href="https://huh.creepermcr.top/maphgu/" target="_blank" rel="noreferrer">https://huh.creepermcr.top/maphgu/</a>，点击工具-驿站与取件码，在这里我们已经将所有快递对应的身份码整合完成，点一下就可以快捷跳转到对应的身份码</p><h3 id="还是不明白" tabindex="-1">还是不明白？ <a class="header-anchor" href="#还是不明白" aria-label="Permalink to &quot;还是不明白？&quot;">​</a></h3><p>向周边的同学或者工作人员寻求帮助</p><h3 id="快递不见了" tabindex="-1">快递不见了？ <a class="header-anchor" href="#快递不见了" aria-label="Permalink to &quot;快递不见了？&quot;">​</a></h3><p>立即向工作人员说明情况，必要时可查监控</p><h3 id="拿错别人的快递怎么办" tabindex="-1">拿错别人的快递怎么办？ <a class="header-anchor" href="#拿错别人的快递怎么办" aria-label="Permalink to &quot;拿错别人的快递怎么办？&quot;">​</a></h3><p>*相信你不是有意而为之</p><ul><li>将快递<strong>送回代收点</strong>，交给工作人员处理</li><li>若快递已经拆开/使用，<strong>主动联系对方商量赔偿措施</strong></li><li>千万不要选择不了了之，即使你是无心<strong>也可能按照盗窃处理</strong></li></ul><h2 id="寄快递" tabindex="-1">寄快递 <a class="header-anchor" href="#寄快递" aria-label="Permalink to &quot;寄快递&quot;">​</a></h2><p>在前台询问工作人员</p>',26)])])}const m=e(i,[["render",o]]);export{p as __pageData,m as default};
